102	async function loadRawYaml(filePath: string): Promise<Record<string, unknown>> {
103	  if (!existsSync(filePath)) return {};
104	  const raw = await readFile(filePath, 'utf8');
105	  const parsed: unknown = yaml.load(raw);
106	  if (parsed === null || parsed === undefined) return {};
107	  if (typeof parsed !== 'object' || Array.isArray(parsed)) return {};
108	  return parsed as Record<string, unknown>;
109	}
