111	/**
112	 * Load a persona YAML file and return it as a plain metadata record.
113	 * The `name` field is derived from the filename stem when absent.
114	 *
115	 * @param yamlPath  Absolute path to the persona YAML file
116	 * @returns         Merged metadata record ready for context building
117	 */
118	async function loadPersonaYaml(yamlPath: string): Promise<Record<string, unknown>> {
119	  const raw = await readFile(yamlPath, 'utf8');
120	  const parsed: unknown = yaml.load(raw);
121	
122	  if (parsed === null || parsed === undefined || typeof parsed !== 'object' || Array.isArray(parsed)) {
123	    throw new Error(`buildPersona: expected a YAML object in "${yamlPath}"`);
124	  }
125	
126	  const record = parsed as Record<string, unknown>;
127	
128	  // Derive name from filename stem if not present in YAML
129	  if (!record['name']) {
130	    record['name'] = path.basename(yamlPath, '.yaml');
131	  }
132	
133	  return record;
134	}
