136	/**
137	 * Resolve the output directory for a given target from a suite configuration.
138	 *
139	 * Resolution order (first match wins):
140	 *   1. `suiteConfig.outputDirs[definition.outputDirKey]` — generic map, takes precedence.
141	 *   2. `suiteConfig.outVscode` — deprecated fallback for the built-in 'vscode' key.
142	 *   3. `suiteConfig.outClaudeCode` — deprecated fallback for the built-in 'claude-code' key.
143	 *
144	 * The lookup key is `definition.outputDirKey` when a registry definition is
145	 * provided, falling back to the raw `target` name for unregistered targets
146	 * (where `outputDirKey` equals the name by convention).
147	 *
148	 * @param target      The build target name.
149	 * @param suiteConfig The suite configuration to resolve from.
150	 * @param definition  Optional registry definition for the target. When present,
151	 *                    `definition.outputDirKey` is used as the output dir map key.
152	 * @returns           Resolved output directory path.
153	 * @throws {Error}    When no output directory is configured for the target.
154	 */
155	function resolveOutputDir(
156	  target: string,
157	  suiteConfig: SuiteConfig,
158	  definition?: TargetDefinition,
159	): string {
160	  // Build a merged map: deprecated named fields provide the base, outputDirs overrides.
161	  const merged: Record<string, string> = {};
162	  if (suiteConfig.outVscode) merged['vscode'] = suiteConfig.outVscode;
163	  if (suiteConfig.outClaudeCode) merged['claude-code'] = suiteConfig.outClaudeCode;
164	  if (suiteConfig.outputDirs) Object.assign(merged, suiteConfig.outputDirs);
165	
166	  // Use outputDirKey from the registry definition when available, falling back
167	  // to the target name for unregistered targets where outputDirKey === name.
168	  const lookupKey = definition?.outputDirKey ?? target;
169	  const dir = merged[lookupKey];
170	  if (dir) return dir;
171	
172	  throw new Error(
173	    `buildPersona: no output directory configured for target "${target}". ` +
174	      `Add outputDirs['${lookupKey}'] to the suite config, or, for the built-in ` +
175	      `targets, provide the outVscode / outClaudeCode fields.`,
176	  );
177	}
