179	/**
180	 * Pre-scan all suites and build a cross-suite agent name map.
181	 *
182	 * For each persona across all configured suites, creates a context variable:
183	 *   key:   `agent_` + slug (hyphens → underscores)
184	 *   value: `"<name> v<version>"`
185	 *
186	 * Slug is taken from the persona YAML's `slug` field, falling back to the
187	 * filename stem. Version falls back to the suite's `default_version`, then
188	 * to `'0.0.0'`.
189	 *
190	 * @param config  Top-level BuildConfig with all suite definitions
191	 * @returns       Map of agent variable keys to display strings
192	 */
193	async function buildAgentNameMap(
194	  config: BuildConfig,
195	): Promise<Record<string, string>> {
196	  const agentMap: Record<string, string> = {};
197	
198	  for (const [, suiteConfig] of Object.entries(config.suites)) {
199	    const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
200	    const sharedYamlPath = path.join(suiteConfig.srcDir, metaSubdir, '_shared.yaml');
201	    const sharedMeta = await loadRawYaml(sharedYamlPath);
202	    const defaultVersion =
203	      typeof sharedMeta['default_version'] === 'string'
204	        ? sharedMeta['default_version']
205	        : '0.0.0';
206	
207	    const personaYamls = await discoverSuitePersonaYamls(suiteConfig);
208	
209	    for (const yamlPath of personaYamls) {
210	      const persona = await loadPersonaYaml(yamlPath);
211	
212	      const slug =
213	        typeof persona['slug'] === 'string'
214	          ? persona['slug']
215	          : path.basename(yamlPath, '.yaml');
216	
217	      const name =
218	        typeof persona['name'] === 'string'
219	          ? persona['name']
220	          : slug;
221	
222	      const version =
223	        typeof persona['version'] === 'string'
224	          ? persona['version']
225	          : defaultVersion;
226	
227	      const underscoredSlug = slug.replace(/-/g, '_');
228	      const key = `agent_${underscoredSlug}`;
229	      agentMap[key] = `${name} v${version}`;
230	
231	      const slugKey = `agent_slug_${underscoredSlug}`;
232	      agentMap[slugKey] = slug;
233	    }
234	  }
235	
236	  return agentMap;
237	}
